\begin{ex}%[6H4V1]
\immini[thm]{
Đếm số hình vuông trong hình sau
}{
\begin{tikzpicture}
    % Vẽ lưới 3x3
    \draw[step=1cm] (0, 0) grid (3, 3);

    % Vẽ viền ngoài của hình vuông 3x3
    \draw[thick] (0, 0) rectangle (3, 3);

    % Vẽ các vòng tròn đặc tại các đỉnh và giao điểm
    \fill (0, 0) circle (2pt);
    \fill (0, 1) circle (2pt);
    \fill (0, 2) circle (2pt);
    \fill (0, 3) circle (2pt);

    \fill (1, 0) circle (2pt);
    \fill (1, 1) circle (2pt);
    \fill (1, 2) circle (2pt);
    \fill (1, 3) circle (2pt);

    \fill (2, 0) circle (2pt);
    \fill (2, 1) circle (2pt);
    \fill (2, 2) circle (2pt);
    \fill (2, 3) circle (2pt);

    \fill (3, 0) circle (2pt);
    \fill (3, 1) circle (2pt);
    \fill (3, 2) circle (2pt);
    \fill (3, 3) circle (2pt);

\end{tikzpicture}
}
\loigiai{
Số hình vuông có cạnh bằng 1 là $9$\\
Số hình vuông có cạnh là 2 bằng $4$\\
Số hình vuông có cạnh là 3 bằng $1$\\
Có $14$ hình vuông trong hình
}\end{ex}
